#!/usr/bin/env node
// scaffold-toast-system.js — v78 ship a canonical Sonner-based toast
// system so the LLM doesn't reinvent it. Emits:
//   - app/components/ui/sonner.tsx     (Shadcn-canonical Sonner wrapper)
//   - app/lib/toast.ts                  (typed toast.success/error/info/warning)
// Registers `sonner` in package.json deps if absent.
//
// Idempotent. Marker: '// Generated by scaffold-toast-system'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-toast-system --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-toast-system — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-toast-system/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

var SONNER_TSX = [
  marker(),
  "import { Toaster as Sonner, type ToasterProps } from 'sonner';",
  "import { useTheme } from 'next-themes';",
  '',
  "export function Toaster(props: ToasterProps) {",
  "  const { theme = 'system' } = (useTheme?.() ?? {}) as { theme?: string };",
  '  return (',
  "    <Sonner",
  "      theme={theme as ToasterProps['theme']}",
  "      className=\"toaster group\"",
  "      toastOptions={{",
  "        classNames: {",
  "          toast: 'group toast group-[.toaster]:bg-background group-[.toaster]:text-foreground group-[.toaster]:border-border group-[.toaster]:shadow-lg',",
  "          description: 'group-[.toast]:text-muted-foreground',",
  "          actionButton: 'group-[.toast]:bg-primary group-[.toast]:text-primary-foreground',",
  "          cancelButton: 'group-[.toast]:bg-muted group-[.toast]:text-muted-foreground',",
  "        },",
  "      }}",
  "      {...props}",
  "    />",
  '  );',
  '}',
  '',
].join('\n');

var TOAST_LIB = [
  marker(),
  "import { toast as sonnerToast } from 'sonner';",
  '',
  '// Thin typed facade so the LLM has ONE place to call toasts from.',
  "// All call sites should: import { toast } from '~/lib/toast'.",
  'export const toast = {',
  "  success: (msg: string, opts?: Parameters<typeof sonnerToast.success>[1]) => sonnerToast.success(msg, opts),",
  "  error: (msg: string, opts?: Parameters<typeof sonnerToast.error>[1]) => sonnerToast.error(msg, opts),",
  "  info: (msg: string, opts?: Parameters<typeof sonnerToast.info>[1]) => sonnerToast.info(msg, opts),",
  "  warning: (msg: string, opts?: Parameters<typeof sonnerToast.warning>[1]) => sonnerToast.warning(msg, opts),",
  "  promise: <T,>(p: Promise<T>, msgs: { loading: string; success: string; error: string }) => sonnerToast.promise(p, msgs),",
  '};',
  '',
].join('\n');

function ensureDep(pkgPath, deps, dryRun) {
  if (!fs.existsSync(pkgPath)) return { changed: false, reason: 'no-package-json' };
  var pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); } catch (_) { return { changed: false, reason: 'parse-error' }; }
  pkg.dependencies = pkg.dependencies || {};
  var added = [];
  Object.keys(deps).forEach(function (k) {
    if (!pkg.dependencies[k] && !(pkg.devDependencies || {})[k]) {
      pkg.dependencies[k] = deps[k];
      added.push(k);
    }
  });
  if (!added.length) return { changed: false, reason: 'already-present' };
  if (dryRun) return { changed: false, reason: 'dry-run', added: added };
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return { changed: true, added: added };
}

function main() {
  var args = parseArgs(process.argv);
  var pkgPath = path.join(args.target, 'package.json');
  var r1 = writeIfManaged(path.join(args.target, 'app/components/ui/sonner.tsx'), SONNER_TSX, args.force, args.dryRun);
  var r2 = writeIfManaged(path.join(args.target, 'app/lib/toast.ts'), TOAST_LIB, args.force, args.dryRun);
  var r3 = ensureDep(pkgPath, { 'sonner': '^1.5.0' }, args.dryRun);
  console.log('scaffold-toast-system:',
    'sonner.tsx=' + (r1.written ? 'wrote' : r1.reason),
    '/ toast.ts=' + (r2.written ? 'wrote' : r2.reason),
    '/ deps=' + (r3.changed ? '+' + r3.added.join(',') : r3.reason));
}

main();
